// CSD_RATIONALE_BEGIN
// Root cause (attempts 60-62): avg generated tokens = 8.68 (median 7).
// The model generates short but technically-complete SQL like "SELECT city" and
// the parser closes the span at the first IsCompletePrefix=true point, producing
// queries missing FROM, WHERE, JOIN, GROUP BY etc. RegenerateUnitOnGroundingFailure
// (attempt 61) also terminates early because the model generates EOS after short SQL.
//
// Two-pronged fix:
// (a) BoostedConstrainedStep with SQL structural keywords (FROM, WHERE, JOIN,
//     GROUP BY, HAVING, ORDER BY, ON, AND) + schema tokens from validTokenGroups
//     — interleaved AFTER GenerateLogits inside the helper, so the boost sticks.
//     This steers the model toward complete SQL structure rather than stopping at
//     "SELECT col".
// (b) Minimum 15-token guard before CloseSpanIfComplete is called. Prevents
//     premature closure for short but technically-valid SQL fragments.
//
// Attempt 60 (min=8, no boosting) got 47.3% — worse because without keyword
// boosting the model generated repetitive/random filler past the minimum. With
// strong keyword + schema boosting, the model generates meaningful SQL structure.
//
// Structure:
//   Phase 1: 4-step unconstrained preamble → emit "SQL: <<"
//   Phase 2: Force "<<" via OpenConstrainedSpan if needed
//   Phase 3: BoostedConstrainedStep loop (≤250 steps), close only after ≥15 tokens
//   Phase 4: CloseSpanWithinBudget(60) safety net
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1: Guard !insideConstrainedOut makes the implication vacuous throughout.
//   The only true-flip is RenderedEndsWith("<<"); we simultaneously set
//   currentConstrainedOut := [] and IsValidPrefix([]) holds by method precondition.
//   EOS break leaves insideConstrainedOut false. ✓
//
// Phase 2: OpenConstrainedSpan postcondition gives currentConstrainedOut := [].
//   IsValidPrefix([]) holds by precondition; only runs when !insideConstrainedOut. ✓
//
// Phase 3 inner loop (both |currentConstrainedOut| >= 15 and < 15 paths):
//   closed=true branch: CloseSpanIfComplete delegates to CloseConstrainedSpan,
//     setting insideConstrainedOut=false. Implication vacuously true;
//     currentConstrainedOut := []. ✓
//   closed=false + valid token: BoostedConstrainedStep has same postcondition as
//     ConstrainedStep (hard-masked, parser-valid or EOS). IsTokenValidNext confirms.
//     AppendConstrainedToken extends currentConstrainedOut by one grammar-valid token,
//     preserving parser.IsValidPrefix by grammar prefix-closure. ✓
//   closed=false + EOS: break without modifying currentConstrainedOut. Invariant
//     carried from prior iteration. ✓
//   |currentConstrained| < 15: BoostedConstrainedStep same as above; no close
//     attempted. Parser validity preserved on AppendConstrainedToken. ✓
//
// Phase 4 CloseSpanWithinBudget: postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut). ✓
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs +1, appends ≤1 token (0 on EOS).
//   steps grows by 1, |generated| by ≤1 each iteration. ✓
//
// Phase 2: OpenConstrainedSpan appends exactly "<<" (1 token), steps += 1.
//   Net 1:1 growth. ✓
//
// Phase 3 (inner loop invariant: |generated| <= |generatedPrefix| + steps + sqlSteps):
//   closed=true: CloseSpanIfComplete (cost +1) appends ">>" (≤1 token);
//     sqlSteps += 1. Growth ≤1:1. ✓
//   closed=false: CloseSpanIfComplete (cost +0, no-op); BoostedConstrainedStep
//     (cost +1) appends ≤1 token (0 on EOS); sqlSteps += 1. Growth ≤1:1. ✓
//   |currentConstrained| < 15: BoostedConstrainedStep (cost +1) appends ≤1 token;
//     sqlSteps += 1. Growth ≤1:1. ✓
//   After loop: steps := steps + sqlSteps. Outer bound restored. ✓
//
// Phase 4: CloseSpanWithinBudget postcondition |generatedOut| <= |generated| + closeBudget;
//   steps += closeBudget. Outer invariant maintained by transitivity. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Generate a complete SQL query. Format: SQL: <<query>>. Include SELECT with exact column names from schema, FROM with exact table name(s), explicit JOIN ... ON ... for multiple tables, WHERE for filtering conditions, GROUP BY/HAVING for aggregation, ORDER BY/LIMIT for ranking. No table aliases. Use only schema tables and columns.");

var steps: nat := 0;

// Phase 1: Short preamble (up to 4 steps) to emit "SQL: <<" naturally
while steps < maxSteps && steps < 4 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Prepare boosted token set: SQL structural keywords + schema tokens, intersected with vocabulary
var sqlKeywords := ["FROM", " FROM", "WHERE", " WHERE", "JOIN", " JOIN",
                    "GROUP", " GROUP", "BY", " BY", "HAVING", " HAVING",
                    "ORDER", " ORDER", "ON", " ON", "AND", " AND",
                    "INNER", " INNER", "LEFT", " LEFT", "COUNT", " COUNT",
                    "SUM", " SUM", "MAX", " MAX", "MIN", " MIN", "AVG", " AVG",
                    "DISTINCT", " DISTINCT", "LIMIT", " LIMIT", "NOT", " NOT",
                    "IN", " IN", "BETWEEN", " BETWEEN", "LIKE", " LIKE",
                    "AS", " AS", "SELECT", " SELECT", "UNION", " UNION"];
var flatSchema := CSDHelpers.FlattenTokenGroups(validTokenGroups);
var combinedBoost := flatSchema + sqlKeywords;
var safeBoost := CSDHelpers.IntersectTokenSets(combinedBoost, lm.Tokens);

// Phase 3: Constrained SQL generation with keyword/schema boosting
// Reserve 60 steps for Phase 4 close; cap Phase 3 at 250 steps
var sqlBudget: nat;
if maxSteps - steps > 60 {
  var rawBudget := maxSteps - steps - 60;
  if rawBudget < 250 {
    sqlBudget := rawBudget;
  } else {
    sqlBudget := 250;
  }
} else {
  sqlBudget := 0;
}

var sqlSteps: nat := 0;

while sqlSteps < sqlBudget && insideConstrainedOut
  invariant 0 <= sqlSteps <= sqlBudget
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps + sqlSteps
  decreases sqlBudget - sqlSteps
{
  if |currentConstrainedOut| >= 15 {
    // Allow closure only after minimum tokens to prevent short-SQL early exit
    var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    if closed {
      generated := cg;
      insideConstrainedOut := ci;
      currentConstrainedOut := cc;
      sqlSteps := sqlSteps + 1;
    } else {
      // CloseSpanIfComplete cost +0 on no-op path; take one boosted constrained step
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.BoostedConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, safeBoost, 2.5, eosToken);
      sqlSteps := sqlSteps + 1;
      if next == eosToken {
        break;
      } else {
        var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
        if valid {
          var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
          generated := ag;
          currentConstrainedOut := ac;
        }
      }
    }
  } else {
    // Under minimum length: force generation without allowing early closure
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.BoostedConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, safeBoost, 2.5, eosToken);
    sqlSteps := sqlSteps + 1;
    if next == eosToken {
      break;
    } else {
      var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
      if valid {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        currentConstrainedOut := ac;
      }
    }
  }
}
steps := steps + sqlSteps;

// Phase 4: Close span via CloseSpanWithinBudget safety net
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 60 {
    closeBudget := remaining;
  } else {
    closeBudget := 60;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

